42: void Database::Process() {
43:     Napi::Env env = this->Env();
44:     Napi::HandleScope scope(env);
45: 
46:     if (!open && locked && !queue.empty()) {
47:         EXCEPTION(Napi::String::New(env, "Database handle is closed"), SQLITE_MISUSE, exception);
48:         Napi::Value argv[] = { exception };
49:         bool called = false;
50: 
51:         // Call all callbacks with the error object.
52:         while (!queue.empty()) {
53:             std::unique_ptr<Call> call(queue.front());
54:             queue.pop();
55:             std::unique_ptr<Baton> baton(call->baton);
56:             Napi::Function cb = baton->callback.Value();
57:             if (!cb.IsUndefined() && cb.IsFunction()) {
58:                 TRY_CATCH_CALL(this->Value(), cb, 1, argv);
59:                 called = true;
60:             }
61:         }
62: 
63:         // When we couldn't call a callback function, emit an error on the
64:         // Database object.
65:         if (!called) {
66:             Napi::Value info[] = { Napi::String::New(env, "error"), exception };
67:             EMIT_EVENT(Value(), 2, info);
