793: Napi::Value Statement::RowToJS(Napi::Env env, Row* row) {
794:     Napi::EscapableHandleScope scope(env);
795: 
796:     Napi::Object result = Napi::Object::New(env);
797: 
798:     Row::const_iterator it = row->begin();
799:     Row::const_iterator end = row->end();
800:     for (int i = 0; it < end; ++it, i++) {
801:         Values::Field* field = *it;
802: 
803:         Napi::Value value;
804: 
805:         switch (field->type) {
806:             case SQLITE_INTEGER: {
807:                 value = Napi::Number::New(env, ((Values::Integer*)field)->value);
808:             } break;
809:             case SQLITE_FLOAT: {
810:                 value = Napi::Number::New(env, ((Values::Float*)field)->value);
811:             } break;
812:             case SQLITE_TEXT: {
813:                 value = Napi::String::New(env, ((Values::Text*)field)->value.c_str(), ((Values::Text*)field)->value.size());
814:             } break;
815:             case SQLITE_BLOB: {
816:                 value = Napi::Buffer<char>::Copy(env, ((Values::Blob*)field)->value, ((Values::Blob*)field)->length);
817:             } break;
818:             case SQLITE_NULL: {
819:                 value = env.Null();
820:             } break;
821:         }
822: 
823:         (result).Set(Napi::String::New(env, field->name.c_str()), value);
824: 
825:         DELETE_FIELD(field);
826:     }
827: 
828:     return scope.Escape(result);
829: }
