831: void Statement::GetRow(Row* row, sqlite3_stmt* stmt) {
832:     int rows = sqlite3_column_count(stmt);
833: 
834:     for (int i = 0; i < rows; i++) {
835:         int type = sqlite3_column_type(stmt, i);
836:         const char* name = sqlite3_column_name(stmt, i);
837:         switch (type) {
838:             case SQLITE_INTEGER: {
839:                 row->push_back(new Values::Integer(name, sqlite3_column_int64(stmt, i)));
840:             }   break;
841:             case SQLITE_FLOAT: {
842:                 row->push_back(new Values::Float(name, sqlite3_column_double(stmt, i)));
843:             }   break;
844:             case SQLITE_TEXT: {
845:                 const char* text = (const char*)sqlite3_column_text(stmt, i);
846:                 int length = sqlite3_column_bytes(stmt, i);
847:                 row->push_back(new Values::Text(name, length, text));
848:             } break;
849:             case SQLITE_BLOB: {
850:                 const void* blob = sqlite3_column_blob(stmt, i);
851:                 int length = sqlite3_column_bytes(stmt, i);
852:                 row->push_back(new Values::Blob(name, length, blob));
853:             }   break;
854:             case SQLITE_NULL: {
855:                 row->push_back(new Values::Null(name));
856:             }   break;
857:             default:
858:                 assert(false);
859:         }
860:     }
861: }
