899: void Statement::CleanQueue() {
900:     Napi::Env env = this->Env();
901:     Napi::HandleScope scope(env);
902: 
903:     if (prepared && !queue.empty()) {
904:         // This statement has already been prepared and is now finalized.
905:         // Fire error for all remaining items in the queue.
906:         EXCEPTION(Napi::String::New(env, "Statement is already finalized"), SQLITE_MISUSE, exception);
907:         Napi::Value argv[] = { exception };
908:         bool called = false;
909: 
910:         // Clear out the queue so that this object can get GC'ed.
911:         while (!queue.empty()) {
912:             std::unique_ptr<Call> call(queue.front());
913:             queue.pop();
914: 
915:             std::unique_ptr<Baton> baton(call->baton);
916:             Napi::Function cb = baton->callback.Value();
917: 
918:             if (prepared && !cb.IsEmpty() &&
919:                 cb.IsFunction()) {
920:                 TRY_CATCH_CALL(Value(), cb, 1, argv);
921:                 called = true;
922:             }
923:         }
924: 
925:         // When we couldn't call a callback function, emit an error on the
926:         // Statement object.
927:         if (!called) {
928:             Napi::Value info[] = { Napi::String::New(env, "error"), exception };
