933:         // Just delete all items in the queue; we already fired an event when
934:         // preparing the statement failed.
935:         std::unique_ptr<Call> call(queue.front());
936:         queue.pop();
937:         // We don't call the actual callback, so we have to make sure that
938:         // the baton gets destroyed.
